	ScAcct  string
	ScPrin  decimal.Decimal
	ScRate  decimal.Decimal
	ScYears int64
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.New(0, 0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string

var schedRec SchedRec
var schedFileLines []string
var schedFileIdx int
var inputDone bool

func formatPIC99(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if v < 0 {
		// handle negative truncate: keep sign? not needed for this program
	}
	return s
}

func formatZZZZZZZZ9_99(val decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99  -> 8 integer digits, 2 decimal digits, width 13
	// Handle negative: COBOL would have sign? Not needed here values positive.
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// Truncate to scale 2 (already) and get integer part
	// Round should already be done; ensure 2 decimal places
	val = val.Truncate(2)
	// Extract integer and fractional parts
	// Use string representation to avoid float errors
	// val = integerPart + frac/100
	// Get total cents as integer
	cents := val.Mul(decimal.New(100, 0)).Truncate(0)
	// cents may be large; get as int64 if fits else via string
	// Use decimal to split
	intPart := cents.Div(decimal.New(100, 0)).Truncate(0)
	fracPart := cents.Mod(decimal.New(100, 0)).IntPart() // 0-99
	// High-order truncation: keep low 8 digits of integer part
	// intPart may exceed 1e8
	modBase := int64(100000000)
	// Use decimal mod for large values
	ten8 := decimal.New(100000000, 0)
	if intPart.Cmp(ten8) >= 0 {
		intPart = intPart.Mod(ten8)
	}
	intStr := intPart.String() // no sign
	// Pad to 8 digits with leading zeros
	if len(intStr) < 8 {
		intStr = strings.Repeat("0", 8-len(intStr)) + intStr
	} else if len(intStr) > 8 {
		intStr = intStr[len(intStr)-8:]
	}
	fracStr := fmt.Sprintf("%02d", fracPart)
	if fracPart < 0 {
		fracPart = -fracPart
		fracStr = fmt.Sprintf("%02d", fracPart)
	}

	// Build formatted array of length 13 with pattern "ZZ,ZZZ,ZZ9.99"
	// digit positions indices in the picture:
	// 0:Z 1:Z 2:, 3:Z 4:Z 5:Z 6:, 7:Z 8:Z 9:9 10:. 11:9 12:9
	pic := []rune("ZZ,ZZZ,ZZ9.99")
	digitPos := []int{0, 1, 3, 4, 5, 7, 8, 9} // 8 integer digit positions
	// Fill integer digits
	out := make([]rune, len(pic))
	copy(out, pic)
	for i, pos := range digitPos {
		out[pos] = rune(intStr[i])
	}
	// Fill decimal digits
	out[11] = rune(fracStr[0])
	out[12] = rune(fracStr[1])

	// Z suppression: leading zeros become spaces, commas in suppressed zone become spaces
	// Find last suppressed Z position: suppression applies to all Z's until first non-zero digit
	// For this picture, digit positions 0,1,3,4,5,7,8 are Z's, position 9 is 9 (always)
	// Leading zero suppression goes left to right: if all integer digits are zero, they become spaces
	// except the 9 position always shows 0.
	// Algorithm: scan digit positions in order; if we have not yet encountered a non-zero digit,
	// replace that digit with space. Once we encounter non-zero, stop suppression.
	suppress := true
	for _, pos := range digitPos {
		if out[pos] != '0' {
			suppress = false
			break
		}
		// if it's zero and still suppressing, turn to space
		if suppress {
			out[pos] = ' '
		}
	}
	if suppress {
		// all Z digits are zero -> they are all spaces (already)
		// keep 9 as '0' (intStr last char is '0')
	} else {
		// Need to actually apply suppression: replace leading Z zeros with spaces until first non-zero
		found := false
		for _, pos := range digitPos {
			if out[pos] != ' ' && out[pos] != '0' {
				found = true
			}
			if !found && out[pos] == '0' {
				out[pos] = ' '
			} else if !found && out[pos] == ' ' {
				// already space
			} else {
				// after first non-zero, keep as is (including zeros)
				found = true
			}
		}
	}
	// Commas in suppressed zone become spaces: comma is suppressed if all digit positions to its left are spaces
	// Commas at index 2 and 6
	commaPositions := []int{2, 6}
	for _, cpos := range commaPositions {
		// check if every digit position left of this comma is space
		allSpace := true
		for _, dp := range digitPos {
			if dp < cpos {
				if out[dp] != ' ' {
					allSpace = false
					break
				}
			}
		}
		if allSpace {
			out[cpos] = ' '
		}
	}
	_ = neg
	return string(out)
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, 0)
	}
	// s contains only digits (maybe spaces). Parse as integer.
	// Remove spaces
	s = strings.ReplaceAll(s, " ", "0")
	// If empty after?
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback: parse as int64
		var v int64
		fmt.Sscan(s, &v)
		d = decimal.New(v, 0)
	}
	return d.Shift(-scale)
}

func parseInt64Digits(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	fmt.Sscan(s, &v)
	return v
}

func loadSchedFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty (COBOL would error)
		schedFileLines = []string{}
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		// COBOL LINE SEQUENTIAL strips trailing newline, keep content as is
		// Do not Trim; pad later
		schedFileLines = append(schedFileLines, line)
	}
}

func READ_PARA() {
	if schedFileIdx >= len(schedFileLines) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	raw := schedFileLines[schedFileIdx]
	schedFileIdx++
	// Pad with spaces to 16
	if len(raw) < 16 {
		raw = raw + strings.Repeat(" ", 16-len(raw))
	}
	if len(raw) > 16 {
		raw = raw[:16]
	}
	schedRec.ScAcct = raw[0:4]
	schedRec.ScPrin = parseDecimalDigits(raw[4:11], 2)
	schedRec.ScRate = parseDecimalDigits(raw[11:15], 2)
	schedRec.ScYears = parseInt64Digits(raw[15:16])
}

func PROCESS_PARA() {
	WsBal = schedRec.ScPrin
	WsYear = 1
	for WsYear <= schedRec.ScYears {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		onePlus := decimal.New(1, 0).Add(schedRec.ScRate.Shift(-2))
		WsBal = WsBal.Mul(onePlus).Round(2)
		// Truncate/store to PIC 9(8)V99 (scale 2, keep low 8 digits)
		// Round already to 2, now apply truncation if needed (scale already 2)
		WsBalEd = formatZZZZZZZZ9_99(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatPIC99(WsYear, 2)
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, yearStr, WsBalEd)
		WsYear++
	}
	WsBalEd = formatZZZZZZZZ9_99(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount++
	// overflow truncate for PIC 99
	if WsCount > 99 {
		WsCount = WsCount % 100
	}
	READ_PARA()
}

func MAIN_PARA() {
	loadSchedFile()
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	countStr := formatPIC99(WsCount, 2)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func main() {
	MAIN_PARA()
}

